private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Decode the octets using the UTF-8 decoding
    int octet = bb.get(i);
    if ((octet & 0x80) == 0) {
        // 1-byte character
        sb.append((char) octet);
        return i + 1;
    } else if ((octet & 0xE0) == 0xC0) {
        // 2-byte character
        int octet2 = bb.get(i + 1);
        sb.append((char) (((octet & 0x1F) << 6) | (octet2 & 0x3F)));
        return i + 2;
    } else if ((octet & 0xF0) == 0xE0) {
        // 3-byte character
        int octet2 = bb.get(i + 1);
        int octet3 = bb.get(i + 2);
        sb.append((char) (((octet & 0x0F) << 12) | ((octet2 & 0x3F) << 6) | (octet3 & 0x3F)));
        return i + 3;
    } else if ((octet & 0xF8) == 0xF0) {
        // 4-byte character
        int octet2 = bb.get(i + 1);
        int octet3 = bb.get(i + 2);
        int octet4 = bb.get(i + 3);
        sb.append((char) (((octet & 0x07) << 18) | ((octet2 & 0x3F) << 12) | ((octet3 & 0x3F) << 6) | (octet4 & 0x3F)));
        return i + 4;
    } else {
        // Invalid octet
        throw new IllegalArgumentException("Invalid octet: " + octet);
    }
}

