public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Check if the input parameters are valid
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    // Get the length of the string
    int length = str.length();

    // Check if the string is empty
    if (length == 0) {
        return lb;
    }

    // Get the first character of the string
    char firstChar = str.charAt(0);

    // Check if the first character is a high surrogate
    if (Character.isHighSurrogate(firstChar)) {
        // Check if the string has at least two characters
        if (length < 2) {
            throw new IllegalArgumentException("String has a high surrogate but is too short");
        }

        // Get the second character of the string
        char secondChar = str.charAt(1);

        // Check if the second character is a low surrogate
        if (Character.isLowSurrogate(secondChar)) {
            // Get the code point of the surrogate pair
            int codePoint = Character.toCodePoint(firstChar, secondChar);

            // Write the code point to the buffer
            lb.write(codePoint);
        } else {
            // The second character is not a low surrogate, throw an exception
            throw new IllegalArgumentException("String has a high surrogate but the second character is not a low surrogate");
        }
    } else {
        // The first character is not a high surrogate, write it to the buffer
        lb.write(firstChar);
    }

    // Return the buffer
    return lb;
}

