public final byte[] toByteArray() {
    // Initialize an empty byte array to store the contents of the buffer(s)
    byte[] result = new byte[0];

    // Iterate through each buffer in the list
    for (ByteBuffer buffer : buffers) {
      // Get the current position of the buffer
      int pos = buffer.position();

      // Get the limit of the buffer
      int limit = buffer.limit();

      // Check if the buffer is empty
      if (pos == limit) {
        // Skip this buffer if it is empty
        continue;
      }

      // Get the byte array from the buffer
      byte[] bufferArray = buffer.array();

      // Copy the byte array into the result array
      result = Arrays.copyOf(result, result.length + bufferArray.length);
      System.arraycopy(bufferArray, 0, result, result.length - bufferArray.length, bufferArray.length);
    }

    // Return the result array
    return result;
  }

public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            char nextChar = str.charAt(i + 1);
            if (nextChar == 'n') {
                sb.append('\n');
            } else if (nextChar == 't') {
                sb.append('\t');
            } else if (nextChar == 'r') {
                sb.append('\r');
            } else if (nextChar == 'f') {
                sb.append('\f');
            } else if (nextChar == 'b') {
                sb.append('\b');
            } else if (nextChar == '\\') {
                sb.append('\\');
            } else if (nextChar == '\'') {
                sb.append('\'');
            } else if (nextChar == '\"') {
                sb.append('\"');
            } else {
                sb.append(c);
            }
            i++;
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

