public boolean isCompatible(DataTable dataset) {
    // Check if the dataset is not null
    if (dataset == null) {
        throw new IllegalArgumentException("The dataset cannot be null");
    }

    // Check if the dataset has the same number of columns as the bucket
    if (dataset.getColumnCount() != this.getColumnCount()) {
        return false;
    }

    // Check if the dataset has the same column names as the bucket
    for (int i = 0; i < dataset.getColumnCount(); i++) {
        if (!dataset.getColumnName(i).equals(this.getColumnName(i))) {
            return false;
        }
    }

    // Check if the dataset has the same data types as the bucket
    for (int i = 0; i < dataset.getColumnCount(); i++) {
        if (dataset.getColumnType(i) != this.getColumnType(i)) {
            return false;
        }
    }

    // If all the checks pass, return true
    return true;
}

