public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0 || from < 0 || to < 0 || from > to || to >= arr.length) {
        throw new IllegalArgumentException("Invalid input");
    }

    int start = from;
    int end = to;
    while (start < end) {
        V temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        start++;
        end--;
    }
}

