public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Check if the nameStart is a valid index in the buffer
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid nameStart index: " + nameStart);
    }

    // Check if the buffer is not null
    if (buf == null) {
        throw new NullPointerException("Buffer is null");
    }

    // Abbreviate the name
    String name = buf.substring(nameStart);
    String abbreviation = abbreviateName(name);
    buf.append(abbreviation);
}

private String abbreviateName(String name) {
    // Check if the name is not null or empty
    if (name == null || name.isEmpty()) {
        throw new IllegalArgumentException("Name is null or empty");
    }

    // Abbreviate the name
    String[] words = name.split(" ");
    String abbreviation = "";
    for (String word : words) {
        abbreviation += word.charAt(0);
    }
    return abbreviation;
}

