private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph is null or the set of vertices is empty
    if (graph == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("Graph or vertices cannot be null or empty");
    }

    // Check if all vertices are in the graph
    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            throw new IllegalArgumentException("Vertex " + vertex + " is not in the graph");
        }
    }

    // Check if the subgraph induced by the given vertices is complete
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1 != vertex2 && !graph.containsEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }

    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    for (K key : keys) {
        int lowerBound = 0;
        for (int i = 0; i < keys.size(); i++) {
            if (keys.get(i).compareTo(key) < 0) {
                lowerBound++;
            }
        }
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
}

private void pop(final String descriptor) {
    // Check if the descriptor is a type descriptor
    if (descriptor.startsWith("L") || descriptor.startsWith("[")) {
        // Pop the type from the output frame stack
        outputFrameStack.pop();
    } else {
        // Check if the descriptor is a method descriptor
        if (descriptor.startsWith("(")) {
            // Pop the argument types from the output frame stack
            String[] argumentTypes = descriptor.substring(1).split(";");
            for (String argumentType : argumentTypes) {
                outputFrameStack.pop();
            }
        } else {
            // Throw an IllegalArgumentException if the descriptor is not a type or method descriptor
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }
}

