public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path must not be null");
    }

    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    if (pathParts.length == 0 || relativePathParts.length == 0) {
        throw new IllegalArgumentException("Path and relative path must not be empty");
    }

    StringBuilder result = new StringBuilder();
    for (int i = 0; i < pathParts.length - 1; i++) {
        result.append(pathParts[i]);
        result.append("/");
    }

    for (int i = 0; i < relativePathParts.length; i++) {
        if (relativePathParts[i].equals("..")) {
            if (result.length() == 0) {
                throw new IllegalArgumentException("Relative path cannot move above root");
            }
            int lastSlashIndex = result.lastIndexOf("/");
            result.delete(lastSlashIndex, result.length());
        } else {
            result.append(relativePathParts[i]);
            result.append("/");
        }
    }

    return result.toString();
}

