public Edge edgeToNext() {
    Node currentNode = getCurrentNode();
    Node nextNode = getNextNode();
    if (currentNode == null || nextNode == null) {
        throw new IllegalStateException("Current node or next node is null");
    }
    if (currentNode.isVirtual()) {
        currentNode = currentNode.getRealNode();
    }
    if (nextNode.isVirtual()) {
        nextNode = nextNode.getRealNode();
    }
    return new Edge(currentNode, nextNode);
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        throw new IllegalArgumentException("str and substring cannot be null");
    }
    if (index < 0 || index >= str.length()) {
        throw new IndexOutOfBoundsException("Index " + index + " is out of bounds for string of length " + str.length());
    }
    if (substring.length() > str.length() - index) {
        return false;
    }
    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event) {
    // Write the message to each connected client
    for (Client client : clients) {
        try {
            client.write(event.getMessage());
        } catch (IOException e) {
            // Handle the exception
        }
    }
}

public static String toString(final char ch) {
    if (ch < 128) {
        return ASCII_CHARS[ch];
    } else {
        return String.valueOf(ch);
    }
}

private void checkIfPackedField() throws IOException {
    if (isPackedField()) {
        setPackedFieldState(true);
    }
}

public int readTag() throws IOException {
    int tag = 0;
    try {
        tag = readRawVarint32();
    } catch (InvalidProtocolBufferException e) {
        if (e.getCause() instanceof EOFException) {
            return 0;
        }
        throw e;
    }
    return tag;
}

public ByteVector put11(int byteValue1, int byteValue2) {
    if (byteValue1 < 0 || byteValue1 > 255 || byteValue2 < 0 || byteValue2 > 255) {
        throw new IllegalArgumentException("Invalid byte value");
    }
    ensureCapacity(2);
    byte[] bytes = new byte[2];
    bytes[0] = (byte) byteValue1;
    bytes[1] = (byte) byteValue2;
    System.arraycopy(bytes, 0, this.bytes, this.size, 2);
    this.size += 2;
    return this;
}

private String buildContentRange() {
    String contentRange = "bytes " + startByte + "-" + endByte + "/" + totalBytes;
    return contentRange;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] tokens = line.split(",");
            if (tokens.length != 3) {
                throw new IOException("Invalid file format");
            }
            long timestamp = Long.parseLong(tokens[0]);
            String threadName = tokens[1];
            int threadId = Integer.parseInt(tokens[2]);
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                    threadSnapshots.add(new ThreadSnapshot(timestamp, threadName, threadId));
                }
            }
        }
    }
    return threadSnapshots;
}
